// Client-side search over search-index.json (generated by the build).
// Runs on /search/?q=... — every term must match title or body; results are
// ranked by title hits and occurrence counts.
(function () {
  var params = new URLSearchParams(location.search);
  var q = (params.get('q') || '').trim();
  var box = document.querySelector('.search-form input[name="q"]');
  if (box) box.value = q;

  var status = document.getElementById('search-status');
  var list = document.getElementById('search-results');
  if (!status || !list) return;
  if (!q) {
    status.textContent = 'Type something into the search box to hunt through the cave.';
    return;
  }
  status.textContent = 'Searching…';

  function escapeHtml(s) {
    return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  }

  fetch('/search-index.json')
    .then(function (r) { return r.json(); })
    .then(function (index) {
      var terms = q.toLowerCase().split(/\s+/).filter(Boolean);
      var results = [];

      index.forEach(function (e) {
        var title = e.t.toLowerCase();
        var body = e.x.toLowerCase();
        var score = 0;
        var firstHit = -1;
        var allMatch = terms.every(function (t) {
          var inTitle = title.indexOf(t) !== -1;
          var count = 0;
          var pos = body.indexOf(t);
          if (firstHit === -1 && pos !== -1) firstHit = pos;
          while (pos !== -1 && count < 20) { count++; pos = body.indexOf(t, pos + t.length); }
          score += (inTitle ? 50 : 0) + count;
          return inTitle || count > 0;
        });
        if (allMatch) results.push({ e: e, score: score, at: Math.max(firstHit, 0) });
      });

      results.sort(function (a, b) { return b.score - a.score; });
      results = results.slice(0, 50);

      if (!results.length) {
        status.textContent = 'Nothing found for “' + q + '”.';
        return;
      }
      status.textContent = results.length + (results.length === 50 ? '+' : '') +
        ' result' + (results.length === 1 ? '' : 's') + ' for “' + q + '”:';

      var frag = document.createDocumentFragment();
      results.forEach(function (r) {
        var li = document.createElement('li');
        li.className = 'search-hit';
        var start = Math.max(0, r.at - 60);
        var snippet = escapeHtml((start > 0 ? '…' : '') + r.e.x.slice(start, r.at + 120) + '…');
        terms.forEach(function (t) {
          snippet = snippet.replace(new RegExp('(' + t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + ')', 'gi'), '<mark>$1</mark>');
        });
        li.innerHTML = '<a href="' + r.e.u + '">' + escapeHtml(r.e.t) + '</a>' +
          (r.e.d ? ' <span class="hit-date">' + r.e.d + '</span>' : '') +
          '<p class="hit-snippet">' + snippet + '</p>';
        frag.appendChild(li);
      });
      list.appendChild(frag);
    })
    .catch(function () {
      status.textContent = 'Search is unavailable right now.';
    });
})();
